import {headings,evolution,evaluate} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state={patients:[],shifts:[],audit:[]},tab='patients',selected=null,query='';try{const raw=JSON.parse(localStorage.getItem('zera-v2'));if(raw&&Array.isArray(raw.patients)&&Array.isArray(raw.shifts)&&Array.isArray(raw.audit))state=raw;}catch{setTimeout(()=>toast('Não foi possível ler os dados locais.'),100)}
function save(){try{localStorage.setItem('zera-v2',JSON.stringify(state));return true}catch{toast('Falha ao salvar. Exporte uma cópia antes de fechar.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Texto copiado')}catch{modal(`<h2>Copie o texto abaixo</h2><textarea rows="16">${esc(t)}</textarea><button data-close>Fechar</button>`)}}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelector('[data-close]')?.addEventListener('click',()=>$('#modal').close())}
const current=()=>state.patients.find(p=>p.id===selected);const fmt=d=>new Date(d).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
function download(name,data){const u=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('#date').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));render()});
function render(){if(tab==='shifts')return shifts();if(tab==='handoff')return handoff();const active=state.patients.filter(p=>!['Alta','Internação'].includes(p.status));$('#app').innerHTML=`<div class="title"><div><h1>Seu plantão, em ordem.</h1><p>Do primeiro atendimento à última reavaliação.</p></div><button class="primary" id="new">+ Novo paciente</button></div><div class="stats">${[['Em atendimento',active.length],['Aguardando exames',active.filter(p=>p.status==='Exames').length],['Para reavaliar',active.filter(p=>p.status==='Reavaliação').length],['Concluídos',state.patients.length-active.length]].map(([t,n])=>`<div class="stat"><span>${t}</span><strong>${n.toString().padStart(2,'0')}</strong></div>`).join('')}</div><div class="workspace"><section class="panel"><div class="subhead"><h3>Pacientes</h3><small>${state.patients.length} REGISTROS</small></div><input id="search" placeholder="Buscar identificação ou queixa" aria-label="Buscar paciente" value="${esc(query)}"><div id="list" style="margin-top:15px"></div><div class="actions"><button id="backup">Exportar cópia</button><button id="restore">Importar</button></div><input class="file" id="file" type="file" accept="application/json"></section><section class="panel" id="editor"></section></div>`;$('#new').onclick=newPatient;$('#search').oninput=e=>{query=e.target.value;list()};$('#backup').onclick=()=>download('zera-ps-backup.json',JSON.stringify({version:2,...state},null,2));$('#restore').onclick=()=>$('#file').click();$('#file').onchange=restore;list();editor()}
function list(){$('#list').innerHTML=state.patients.filter(p=>(p.name+' '+p.QP).toLowerCase().includes(query.toLowerCase())).map(p=>`<button class="patient ${p.id===selected?'selected':''}" data-id="${p.id}"><strong>${esc(p.name)}</strong><small>${esc(p.status)} · ${esc(p.QP||'Queixa não informada')}</small></button>`).join('')||'<p style="padding:20px 0">Nenhum paciente nesta lista.</p>';$('#list').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.id;list();editor()})}
function newPatient(){modal(`<h2>Novo atendimento</h2><p>Prefira iniciais ou código. Os dados ficam neste navegador.</p><form id="newform"><label>IDENTIFICAÇÃO<input name="name" required maxlength="80" autofocus placeholder="Ex.: A.S. · Box 2"></label><label>QUEIXA PRINCIPAL<input name="QP" maxlength="400" placeholder="Motivo da admissão"></label><div class="actions"><button class="primary">Iniciar atendimento</button><button type="button" data-close>Cancelar</button></div></form>`);$('#newform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const p={id:crypto.randomUUID(),name:f.get('name').trim(),QP:f.get('QP').trim(),status:'Atendimento',events:[],pending:'',created:new Date().toISOString()};if(!p.name)return;state.patients.unshift(p);selected=p.id;save();$('#modal').close();render()}}
function editor(){const p=current();if(!p){$('#editor').innerHTML='<div class="empty"><small>MENOS DISPERSÃO. MAIS CONTINUIDADE.</small><h2>Um caso de cada vez.</h2><p>Abra um atendimento para registrar a admissão, acompanhar pendências e acrescentar reavaliações sem perder a história.</p><button class="primary" id="start">+ Iniciar atendimento</button></div>';$('#start').onclick=newPatient;return}$('#editor').innerHTML=`<div class="subhead"><div><h2 style="margin:0">${esc(p.name)}</h2><p>Admissão · ${fmt(p.created)}</p></div><div class="actions"><button id="evolve">Copiar evolução</button><button id="remove" class="danger">Excluir</button></div></div><div class="fields"><label>ETAPA DO ATENDIMENTO<select id="status">${['Atendimento','Exames','Reavaliação','Alta','Internação'].map(x=>`<option ${p.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>PENDÊNCIAS<input id="pending" value="${esc(p.pending)}" placeholder="Ex.: resultado da TC, discutir caso"></label>${headings.map(k=>`<label class="${['HDA','CONDUTA'].includes(k)?'wide':''}"># ${k}${k==='HDA'?' · ADMISSÃO':''}<textarea data-field="${k}" placeholder="NA = não informado; NEGA somente quando negado" ${p.events.length?'': ''}>${esc(p[k]||'')}</textarea></label>`).join('')}</div><div class="subhead"><h3>Reavaliações · # EM TEMPO</h3><button class="primary" id="add-event">+ Reavaliar</button></div>${p.events.map(e=>`<div class="event"><small>${fmt(e.at)}</small><p>${esc(e.text)}</p></div>`).join('')||'<p>As atualizações serão acrescentadas em ordem cronológica.</p>'}<div class="note">Campos vazios geram NA. O texto usa apenas os dados registrados e deve ser revisado antes de entrar no prontuário.</div>`;$('#status').onchange=e=>{p.status=e.target.value;save();render()};$('#pending').oninput=e=>{p.pending=e.target.value;save()};document.querySelectorAll('[data-field]').forEach(t=>t.oninput=()=>{p[t.dataset.field]=t.value;save();if(t.dataset.field==='QP')list()});$('#evolve').onclick=()=>copy(evolution(p));$('#add-event').onclick=()=>{modal('<h2>Reavaliação</h2><p>A HDA de admissão será preservada. Registre o que mudou, exames e conduta.</p><form id="eventform"><label># EM TEMPO<textarea name="text" required rows="7" autofocus></textarea></label><button class="primary">Registrar atualização</button> <button type="button" data-close>Cancelar</button></form>');$('#eventform').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;p.events.push({at:new Date().toISOString(),text});save();$('#modal').close();editor()}};$('#remove').onclick=()=>{modal('<h2>Excluir atendimento?</h2><p>Esta ação remove o registro deste navegador. Exporte uma cópia se precisar preservá-lo.</p><button id="yes" class="danger">Excluir registro</button> <button data-close>Cancelar</button>');$('#yes').onclick=()=>{state.patients=state.patients.filter(x=>x.id!==p.id);selected=null;save();$('#modal').close();render()}}}
function handoff(){const ps=state.patients.filter(p=>!['Alta','Internação'].includes(p.status));const text=ps.map(p=>`${p.name.toUpperCase()} · ${p.status.toUpperCase()}\nQP: ${p.QP||'NA'}\nHD: ${p.HD||'NA'}\nEXAMES: ${p.EXAMES||'NA'}\nÚLTIMA ATUALIZAÇÃO: ${p.events.at(-1)?.text||'NA'}\nCONDUTA: ${p.CONDUTA||'NA'}\nPENDÊNCIAS: ${p.pending||'NA'}`).join('\n\n');$('#app').innerHTML=`<div class="title"><div><h1>Continuidade do cuidado.</h1><p>Casos em aberto, informações registradas e próximos passos.</p></div><button id="copyhandoff" class="primary">Copiar passagem</button></div><section class="panel">${text?`<pre>${esc(text)}</pre>`:'<div class="empty"><h2>Nenhum caso em aberto.</h2><p>Os atendimentos ativos aparecem aqui automaticamente.</p></div>'}</section>`;$('#copyhandoff').onclick=()=>text?copy(text):toast('Nenhum caso em aberto')}
function shifts(){$('#app').innerHTML=`<div class="title"><div><h1>Seu próximo plantão.</h1><p>Confira elegibilidade, conflitos e confirme sua agenda.</p></div><button id="newshift" class="primary">+ Adicionar oferta</button></div><div class="note"><strong>Modo local · Portal não conectado</strong><br>Enfermaria de cardiologia e reavaliador bloqueados. Extra de segunda durante o dia permitido. As confirmações abaixo organizam sua agenda local; não aceitam ofertas no portal.</div><section class="panel"><h2>Ofertas e agenda</h2>${state.shifts.map(s=>{const v=evaluate(s,state.shifts);return `<div class="shift"><div><h3>${esc(s.place)}</h3><p>${fmt(s.start)} → ${fmt(s.end)}</p><p>${s.status==='confirmed'?'Confirmado na agenda local':esc(v.reason)}</p></div><div class="actions">${s.status==='confirmed'?`<button data-cancel="${s.id}">Cancelar localmente</button>`:`<button data-confirm="${s.id}" ${v.ok?'class="primary"':'disabled'}>Confirmar na agenda</button>`}</div></div>`}).join('')||'<div class="empty"><h2>A agenda começa aqui.</h2><p>Adicione uma oferta para verificar se ela se encaixa.</p></div>'}</section><section class="panel" style="margin-top:20px"><h3>Histórico de decisões</h3>${state.audit.slice(-20).reverse().map(a=>`<p>${fmt(a.at)} · ${esc(a.text)}</p>`).join('')||'<p>As confirmações e cancelamentos ficam registrados aqui.</p>'}</section>`;$('#newshift').onclick=()=>{modal(`<h2>Adicionar oferta</h2><form id="shiftform"><label>LOCAL<input name="place" required placeholder="Hospital / unidade"></label><label>FUNÇÃO<select name="role"><option value="ps">Pronto-socorro</option><option value="extra">Extra de apoio no PS</option><option value="cardio">Enfermaria cardiologia</option><option value="reavaliador">Reavaliador</option></select></label><div class="fields"><label>INÍCIO<input type="datetime-local" name="start" required></label><label>FIM<input type="datetime-local" name="end" required></label></div><button class="primary">Verificar oferta</button> <button type="button" data-close>Cancelar</button></form>`);$('#shiftform').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(Date.parse(f.end)<=Date.parse(f.start)){toast('O fim precisa ser posterior ao início');return}state.shifts.push({...f,start:new Date(f.start).toISOString(),end:new Date(f.end).toISOString(),id:crypto.randomUUID(),status:'offered'});save();$('#modal').close();shifts()}};document.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>{const s=state.shifts.find(x=>x.id===b.dataset.confirm),v=evaluate(s,state.shifts);if(!v.ok){toast(v.reason);shifts();return}s.status='confirmed';state.audit.push({at:new Date().toISOString(),text:`Confirmação local: ${s.place} · ${fmt(s.start)}`});save();shifts()});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const s=state.shifts.find(x=>x.id===b.dataset.cancel);s.status='offered';state.audit.push({at:new Date().toISOString(),text:`Cancelamento local: ${s.place}`});save();shifts()})}
async function restore(e){try{const d=JSON.parse(await e.target.files[0].text());if(d.version!==2||!Array.isArray(d.patients)||!Array.isArray(d.shifts)||!Array.isArray(d.audit))throw Error();for(const p of d.patients){if(typeof p.id!=='string'||!/^[\w-]+$/.test(p.id)||typeof p.name!=='string'||!Array.isArray(p.events)||!Number.isFinite(Date.parse(p.created))||headings.some(k=>p[k]!=null&&typeof p[k]!=='string')||p.events.some(x=>typeof x.text!=='string'||!Number.isFinite(Date.parse(x.at))))throw Error()}for(const s of d.shifts)if(typeof s.id!=='string'||!/^[\w-]+$/.test(s.id)||typeof s.place!=='string'||!Number.isFinite(Date.parse(s.start))||!Number.isFinite(Date.parse(s.end)))throw Error();if(d.audit.some(x=>typeof x.text!=='string'||!Number.isFinite(Date.parse(x.at))))throw Error();for(const key of ['patients','shifts'])for(const item of d[key])if(!state[key].some(x=>x.id===item.id))state[key].push(item);state.audit.push(...d.audit);save();render();toast('Cópia importada sem substituir registros existentes')}catch{toast('Arquivo inválido. Nenhum dado foi importado.')}}
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
